pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 1;

    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error)
            }
            Err(error) => {
                let retry_number = attempt;
                sleeper.sleep_ms(config.delay_for_retry(retry_number));
                attempt += 1;
                let _ = error;
            }
        }
    }
}

